#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <set>
using namespace std;

int main(){
    set<int>a={1,2,3},b={2,3,4},c={3,4,5},uni=a;
    uni.insert(b.begin(),b.end());
    uni.insert(c.begin(),c.end());
    int ab=0,ac=0,bc=0,abc=0;
    for (int x:a){
        ab+=b.count(x)>0;
        ac+=c.count(x)>0;
        abc+=b.count(x)&&c.count(x);
    }
    for (int x:b)bc+=c.count(x)>0;
    cout<<uni.size()<<" "<<a.size()+b.size()+c.size()-ab-ac-bc+abc<<"\n";
    return 0;
}

