#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <set>
using namespace std;

int main(){
    set<int>omega={1,2,3,4};
    vector<set<int>>family={{},{1,2},{3,4},{1,2,3,4}};
    bool valid=true;
    for (auto a:family){
        set<int>comp;
        for (int x:omega)if (!a.count(x))comp.insert(x);
        if (find(family.begin(),family.end(),comp)==family.end())valid=false;
        for (auto b:family){
            a.insert(b.begin(),b.end());
            if (find(family.begin(),family.end(),a)==family.end())valid=false;
        }
    }
    cout<<valid<<"\n";
    return 0;
}

