#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
    vector<int>truth={0,0,0,1,1,1,1},reject={0,1,0,1,0,1,1};
    int falsePositive=0,falseNegative=0,n0=0,n1=0;
    for (int i=0;i<int(truth.size());i++){
        if (truth[i]==0){
            n0++;
            if (reject[i])falsePositive++;
        }
        else{
            n1++;
            if (!reject[i])falseNegative++;
        }
    }
    cout<<double(falsePositive)/n0<<" "<<double(falseNegative)/n1<<"\n";
    return 0;
}

